CREATE TRIGGER stock_location_guard BEFORE INSERT ON stock_movements WHEN (SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE product_id=NEW.product_id AND location_id=NEW.location_id)+NEW.quantity < -0.000001 BEGIN SELECT RAISE(ABORT,'该库位库存不足，请核对存放位置后再处理'); END;
CREATE TRIGGER stock_usable_guard BEFORE INSERT ON stock_movements WHEN (SELECT usable FROM warehouse_locations WHERE id=NEW.location_id)=1 AND (SELECT COALESCE(SUM(m.quantity),0) FROM stock_movements m JOIN warehouse_locations l ON l.id=m.location_id WHERE m.product_id=NEW.product_id AND l.usable=1)+NEW.quantity < (SELECT COALESCE(SUM(quantity),0) FROM stock_reservations WHERE product_id=NEW.product_id AND status='active')-0.000001 BEGIN SELECT RAISE(ABORT,'可用库存已被占用，请先核对客户或售后占用'); END;
